sections.body:
保存为 inference-queue.mjs，运行 node inference-queue.mjs，无额外依赖。所有时间都是虚拟毫秒，不等待真实时钟。假设单个串行计算槽、每次固定耗时、传输与采样耗时为零；同一时刻先处理完成，再处理新输入。输入停止后继续把队列处理完。

```javascript
/**
 * @file Compare inference scheduling with deterministic virtual time; no model is executed.
 * @author liliwei
 * @date 2026-11-08
 * @LastEditors liliwei
 * @LastEditTime 2026-11-08
 */

/**
 * Replay one serial inference slot; completion wins ties with a new arrival.
 * @param {number[]} arrivals Strictly increasing integer capture times in milliseconds.
 * @param {number} cost Positive simulated service time, not measured model latency.
 * @param {'fifo'|'latest'} mode Keep all pending snapshots or just the newest one.
 * @param {number} budget Maximum capture-to-completion age accepted by the demonstration.
 * @returns {object} Full completion trace and queue accounting, including discarded inputs.
 */
export function replay(arrivals, cost, mode, budget = 300) {
  if (!Array.isArray(arrivals) || arrivals.length > 1000 ||
      !Number.isSafeInteger(cost) || cost < 1 || cost > 10000 ||
      !Number.isSafeInteger(budget) || budget < 1 || budget > 1000000 ||
      !['fifo', 'latest'].includes(mode)) throw new Error('bad settings');
  for (let k = 0; k < arrivals.length; k++) {
    if (!Number.isSafeInteger(arrivals[k]) || arrivals[k] < 0 ||
        arrivals[k] > 1000000 || (k && arrivals[k] <= arrivals[k - 1])) {
      throw new Error('bad capture times');
    }
  }
  let i = 0, active = null, replaced = 0, maxPending = 0;
  const pending = [], rows = [];
  /** @param {object} input Captured snapshot. @param {number} at Start time. @returns {void} */
  const start = (input, at) => { active = { ...input, start: at, done: at + cost }; };
  while (i < arrivals.length || active) {
    const nextArrival = arrivals[i] ?? Infinity;
    if (active && active.done <= nextArrival) {
      const at = active.done;
      const age = at - active.captured;
      rows.push({ ...active, age, usable: age <= budget });
      active = null;
      if (pending.length) start(pending.shift(), at);
    } else {
      const input = { id: i, captured: arrivals[i++] };
      if (!active) start(input, input.captured);
      else {
        if (mode === 'latest' && pending.length) {
          pending[0] = input;
          replaced++;
        } else pending.push(input);
        maxPending = Math.max(maxPending, pending.length);
      }
    }
  }
  return {
    submitted: arrivals.length, completed: rows.length, replaced, maxPending,
    usable: rows.filter(row => row.usable).length,
    maxAge: Math.max(0, ...rows.map(row => row.age)),
    finishedAt: rows.at(-1)?.done ?? null, rows
  };
}

const arrivals = Array.from({ length: 20 }, (_, i) => i * 50);
for (const [mode, cost] of [['fifo', 200], ['latest', 200], ['latest', 400]]) {
  const { rows, ...summary } = replay(arrivals, cost, mode);
  console.log(JSON.stringify({ mode, cost, ...summary, ids: rows.map(row => row.id) }));
}
```

age 包含排队和处理时间；usable 只表示 age≤300。实际 Worker 还应计入特征提取、数据复制、消息传递与 UI 应用时间。这段代码用于解释调度取舍，并不是生产版 Worker 管理器。
